/tmp/audit-work/proc-self-shim.c.content:
#define _GNU_SOURCE

#include <dlfcn.h>
#include <errno.h>
#include <stddef.h>
#include <string.h>
#include <unistd.h>

static int is_numeric_proc_exe(const char *path) {
    static const char prefix[] = "/proc/";
    static const char suffix[] = "/exe";
    size_t prefix_len = sizeof(prefix) - 1;
    size_t suffix_len = sizeof(suffix) - 1;
    size_t length;
    size_t index;

    if (path == NULL || strncmp(path, prefix, prefix_len) != 0) {
        return 0;
    }
    length = strlen(path);
    if (length <= prefix_len + suffix_len ||
        strcmp(path + length - suffix_len, suffix) != 0) {
        return 0;
    }
    for (index = prefix_len; index < length - suffix_len; ++index) {
        if (path[index] < '0' || path[index] > '9') {
            return 0;
        }
    }
    return 1;
}

ssize_t readlink(const char *path, char *buffer, size_t size) {
    static ssize_t (*real_readlink)(const char *, char *, size_t);

    if (real_readlink == NULL) {
        real_readlink = dlsym(RTLD_NEXT, "readlink");
        if (real_readlink == NULL) {
            errno = ENOSYS;
            return -1;
        }
    }
    if (is_numeric_proc_exe(path)) {
        path = "/proc/self/exe";
    }
    return real_readlink(path, buffer, size);
}

ssize_t readlinkat(int directory, const char *path, char *buffer, size_t size) {
    static ssize_t (*real_readlinkat)(int, const char *, char *, size_t);

    if (real_readlinkat == NULL) {
        real_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
        if (real_readlinkat == NULL) {
            errno = ENOSYS;
            return -1;
        }
    }
    if (is_numeric_proc_exe(path)) {
        directory = AT_FDCWD;
        path = "/proc/self/exe";
    }
    return real_readlinkat(directory, path, buffer, size);
}

